sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var answer = {
        "course": {
            "id": null,
            "name": "No Course",
            "start": null,
            "end": null,
            "capacity": 0,
            "min_threshold": 0,
            "attendee_count": 0,
            "course_offering": {
                "value": null,
                "display_value": null
            },
            "state": {
                "value": null,
                "display_value": null
            },
            "assigned_to": {
                "value": null,
                "display_value": null
            },
        },
        "students": []
    };
    var responseStatus = 404;
    var courseName = request.queryParams.name.toString();
    var courseGR = new GlideRecord('x_1931947_web_se_0_training_course');

    if (courseGR.get('name', courseName)) {
        // update the responseStatus
        responseStatus = 200;

        // populate course details
        answer.course = {
            "id": courseGR.getUniqueValue(),
            "name": courseGR.getValue('name'),
            "start": courseGR.getValue('work_start'),
            "end": courseGR.getValue('work_end'),
            "capacity": parseInt(courseGR.getValue('capacity'), 10),
            "min_threshold": parseInt(courseGR.getValue('minimum_threshold'), 10),
            "attendee_count": parseInt(courseGR.getValue('attendee_count'), 10),
            "course_offering": {
                "value": courseGR.getValue('course_offering'),
                "display_value": courseGR.course_offering.getDisplayValue()
            },
            "state": {
                "value": courseGR.getValue('state'),
                "display_value": courseGR.state.getDisplayValue()
            },
            "assigned_to": {
                "value": courseGR.getValue('assigned_to'),
                "display_value": courseGR.assigned_to.getDisplayValue()
            },
        };

		var studentGR = new GlideRecord('x_1931947_web_se_0_training_attendee');
		studentGR.addQuery('course', courseGR.getUniqueValue());
		studentGR.query();

		// populate student array
		while(studentGR.next()) {
			var profileGR = studentGR.employee.getRefRecord();
			var studentObj = {
				"id": studentGR.getUniqueValue(),
				"first_name": profileGR.getValue('first_name'),
				"last_name": profileGR.getValue('last_name'),
				"name": profileGR.getValue('name'),
				"email": profileGR.getValue('email'),
			};
			answer.students.push(studentObj);
		}
    }

	response.setBody(answer);
	response.setStatus(responseStatus);
})(request, response);
